package com.lexorion.payroll.domain;
import jakarta.persistence.*;import java.math.BigDecimal;import java.util.UUID;import lombok.*;import org.hibernate.annotations.Check;import org.hibernate.annotations.UuidGenerator;
@Entity@Check(constraints="configured_value >= 0")@Table(name="payroll_salary_template_components",uniqueConstraints=@UniqueConstraint(name="uk_salary_template_component",columnNames={"template_id","component_definition_id"}),indexes=@Index(name="idx_salary_template_component_template",columnList="template_id"))
@Getter@Setter@NoArgsConstructor public class SalaryTemplateComponent extends Auditable{@Id@UuidGenerator private UUID id;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="template_id",nullable=false,updatable=false)private SalaryTemplate template;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="component_definition_id",nullable=false,updatable=false)private ComponentDefinition definition;@Column(name="configured_value",nullable=false,precision=19,scale=4)private BigDecimal value;}
